import { makeID } from "@/utils";

/** Generates a sequence of hierarchical DOM IDs for rendered nodes. */
export class Idm {
  private counter: number;
  private readonly baseId: string;

  constructor(seed?: string, counter = 0, public readonly nonce?: string) {
    this.baseId = seed || makeID(4);
    this.counter = Number.isSafeInteger(counter) && counter >= 0 ? counter : 0;
  }

  /** Resumes the sequence from an ID previously generated by this class. */
  static fromId(id: string, nonce?: string) {
    const match = /^(.*)-(\d+)$/.exec(id);
    if (!match || !match[1]) return new Idm(id, 0, nonce);
    return new Idm(match[1], Number(match[2]), nonce);
  }

  get id() {
    return `${this.baseId}-${this.counter}`;
  }

  get nextId() {
    return `${this.baseId}-${this.counter++}`;
  }

  get childId() {
    return Idm.fromId(`${this.nextId}-0`, this.nonce);
  }

  append(prefix = "h") {
    return Idm.fromId(`${prefix}${this.id}`, this.nonce);
  }
}
